import React, { useState } from "react";
import { Box, Typography, Paper, useTheme, useMediaQuery, Grow, Toolbar, Grid } from "@mui/material";
import PersonAddOutlinedIcon from '@mui/icons-material/PersonAddOutlined';
import SettingsOutlinedIcon from '@mui/icons-material/SettingsOutlined';
import RocketLaunchOutlinedIcon from '@mui/icons-material/RocketLaunchOutlined';
// --- REMOVED: DrawerAppBar import is no longer needed here ---
// import DrawerAppBar from "../Components/DrawerAppBar";

const steps = [
  {
    number: "01",
    icon: <PersonAddOutlinedIcon sx={{ color: "#28a745", fontSize: 50 }} />,
    title: "Sign Up",
    desc: "Create your account in minutes with our simple onboarding process. No credit card required for free trial.",
  },
  {
    number: "02",
    icon: <SettingsOutlinedIcon sx={{ color: "#28a745", fontSize: 50 }} />,
    title: "Configure",
    desc: "Set up your integrations and customize workflows to match your business needs with our intuitive interface.",
  },
  {
    number: "03",
    icon: <RocketLaunchOutlinedIcon sx={{ color: "#28a745", fontSize: 50 }} />,
    title: "Launch",
    desc: "Go live with your automated processes and start seeing immediate improvements in efficiency and productivity.",
  },
];

export default function HowItWorksPage() {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("md"));
  
  const [hoveredIndex, setHoveredIndex] = useState(null);

  return (
    // --- REMOVED: Fragment, DrawerAppBar, and Toolbar are no longer needed ---
    <Box
      sx={{
        background: "#fff",
        width: "100%",
        // --- UPDATED: 'py' (padding top & bottom) changed to 'pb' (padding bottom only) ---
        pb: { xs: 6, sm: 8, md: 10, lg: 12 },
        pt: { xs: 6, sm: 8, md: 10, lg: 12 }, // Padding-top added back for standalone use, can be removed if needed
        px: { xs: 2, sm: 4 },
        boxSizing: "border-box",
      }}
    >
      <Box
        sx={{
          maxWidth: 1200,
          mx: "auto",
          textAlign: "center",
          mb: { xs: 6, md: 10 },
        }}
      >
        <Typography
          variant="h2"
          sx={{
            fontWeight: 800,
            mb: 2,
            color: "#1a2330",
            fontSize: { xs: "2rem", sm: "2.5rem", md: "3rem", lg: "3.5rem" },
          }}
        >
          How It{" "}
          <span style={{ color: "#28a745" }}>Works</span>
        </Typography>
        <Typography
          sx={{
            maxWidth: 700,
            color: "#415064",
            mx: "auto",
            fontSize: { xs: "1rem", md: "1.125rem" },
          }}
        >
          Get started with BizBridge in three simple steps and transform your
          business operations today.
        </Typography>
      </Box>

      <Grid
        container
        justifyContent="center"
        alignItems="stretch"
        sx={{ maxWidth: 1200, mx: "auto", position: 'relative' }}
      >
        {steps.map((step, idx) => (
          <Grid 
            item 
            xs={12} 
            md={4} 
            key={idx} 
            sx={{ 
              position: 'relative', 
              display: 'flex',
              px: isMobile ? 0 : { md: 3, lg: 4 }, 
              pb: isMobile && idx < steps.length - 1 ? 5 : 0,
            }}
          >
            <Grow in={true} timeout={(idx + 1) * 500}>
              <Paper
                variant="outlined"
                onMouseEnter={() => setHoveredIndex(idx)}
                onMouseLeave={() => setHoveredIndex(null)}
                sx={{
                  p: { xs: 3, sm: 4 },
                  textAlign: "left",
                  borderRadius: "16px",
                  height: '100%',
                  width: '100%',
                  position: 'relative',
                  overflow: 'hidden',
                  transition: 'transform 0.3s ease-in-out, box-shadow 0.3s ease-in-out',
                  borderColor: '#e0e0e0',
                  cursor: 'pointer',
                  '&:hover': {
                    transform: 'translateY(-10px)',
                    boxShadow: '0 8px 25px rgba(0,0,0,0.08)'
                  }
                }}
              >
                <Box
                  sx={{
                    position: 'absolute', top: 20, right: 20, width: 36, height: 36,
                    display: 'flex', alignItems: 'center', justifyContent: 'center',
                    borderRadius: '50%', backgroundColor: '#ffc107', color: '#fff',
                    fontWeight: 'bold', fontSize: '1rem',
                  }}
                >
                  {step.number}
                </Box>

                <Box sx={{ mb: 2 }}>{step.icon}</Box>

                <Typography
                  variant="h5"
                  sx={{
                    fontWeight: 800,
                    color: hoveredIndex === idx ? "#28a745" : "#1a2330",
                    mb: 1,
                    transition: 'color 0.3s ease-in-out',
                  }}
                >
                  {step.title}
                </Typography>
                
                <Typography
                  sx={{
                    color: "#40495e",
                    fontSize: 16,
                    lineHeight: 1.7,
                  }}
                >
                  {step.desc}
                </Typography>
              </Paper>
            </Grow>
            
            {/* Desktop par dikhne waali connecting line */}
            {!isMobile && idx < steps.length - 1 && (
              <Box
                sx={{
                  position: 'absolute', top: '50%', right: 0, width: '50%',
                  transform: 'translateX(50%) translateY(-50%)', height: '2px',
                  backgroundImage: 'linear-gradient(to right, #cccccc 33%, rgba(255,255,255,0) 0%)',
                  backgroundPosition: 'bottom', backgroundSize: '8px 2px',
                  backgroundRepeat: 'repeat-x',
                  zIndex: -1,
                }}
              />
            )}
          </Grid>
        ))}
      </Grid>
    </Box>
  );
}

