import React, { useState } from "react";
import {
  Box,
  Typography,
  Button,
  Divider,
} from "@mui/material";
import { useLocation } from "react-router-dom";

export default function ProductDetails() {
  const location = useLocation();
  const product = location.state?.product;

  const [selectedImage, setSelectedImage] = useState(
    product?.image || product?.images?.[0]
  );

  if (!product) return <Typography>No product data found</Typography>;

  return (
    <Box
      sx={{
        width: "100%",
        minHeight: "100vh",
        backgroundColor: "#f8fafc",
        py: { xs: 2, sm: 3 },
      }}
    >
      {/* Page Title */}
      <Typography
        fontWeight={700}
        fontSize={{ xs: 22, sm: 26, md: 30 }}
        sx={{ px: { xs: 2, sm: 3 }, mb: 2 }}
        color="#22364a"
      >
        Product Details
      </Typography>

      <Box sx={{ px: { xs: 2, sm: 3 } }}>
        {/* Responsive Grid */}
        <Box
          sx={{
            display: "grid",
            gridTemplateColumns: { xs: "1fr", md: "1fr 1.3fr" },
            gap: { xs: 3, sm: 4, md: 6 },
          }}
        >
          {/* LEFT BOX — Images + Add To Cart */}
          <Box>
            {/* Thumbnail List */}
            {product.images?.length > 1 && (
              <Box
                sx={{
                  display: "flex",
                  gap: 1.5,
                  mb: 2,
                  overflowX: "auto",
                  pb: 1,
                }}
              >
                {product.images.map((img, index) => (
                  <Box
                    key={index}
                    component="img"
                    src={img}
                    onClick={() => setSelectedImage(img)}
                    sx={{
                      width: 65,
                      height: 65,
                      objectFit: "cover",
                      borderRadius: 2,
                      cursor: "pointer",
                      border:
                        selectedImage === img
                          ? "2px solid #144c4a"
                          : "1px solid #d1d5db",
                    }}
                  />
                ))}
              </Box>
            )}

            {/* Main Image */}
            <Box
              component="img"
              src={selectedImage}
              sx={{
                width: "100%",
                height: { xs: 260, sm: 330, md: 430, lg: 500 },
                objectFit: "contain",
                borderRadius: 3,
                border: "1px solid #e5e7eb",
                background: "#fff",
                p: { xs: 1.5, sm: 2 },
              }}
            />

            {/* Add to Cart */}
            <Button
              fullWidth
              variant="contained"
              sx={{
                mt: 3,
                py: 1.3,
                background: "#fb8900",
                borderRadius: 2,
                fontWeight: 700,
                fontSize: { xs: 16, sm: 18 },
                textTransform: "none",
                "&:hover": { background: "#fb8a00e2" },
              }}
            >
              Add To Cart
            </Button>
          </Box>

          {/* RIGHT BOX — Details */}
          <Box>
            {/* Product Name */}
            <Typography
              fontSize={{ xs: 22, sm: 26, md: 30 }}
              fontWeight={700}
              sx={{ mb: 1 }}
            >
              {product.name}
            </Typography>

            {/* Price Box */}
            <Box
              sx={{
                p: { xs: 2, sm: 3 },
                borderRadius: 3,
                border: "1px solid #d1d5db",
                mb: 4,
              }}
            >
              <Typography
                sx={{
                  textDecoration: "line-through",
                  fontSize: { xs: 16, sm: 18 },
                  color: "#9ca3af",
                }}
              >
                ₹{product.price.toFixed(2)}
              </Typography>

              <Typography
                sx={{
                  fontSize: { xs: 26, sm: 32, md: 36 },
                  fontWeight: 800,
                  color: "#144c4a",
                  mt: 1,
                }}
              >
                ₹{product.price.toFixed(2)}
              </Typography>

              {product.unit && (
                <Typography
                  sx={{
                    mt: 1,
                    fontSize: { xs: 15, sm: 17 },
                    fontWeight: 600,
                    color: "#374151",
                  }}
                >
                  Unit: {product.unit}
                </Typography>
              )}
            </Box>

            {/* Description */}
            <Typography
              fontSize={{ xs: 20, sm: 22 }}
              fontWeight={700}
              sx={{ mb: 1 }}
            >
              Description
            </Typography>

            <Typography
              sx={{
                color: "#374151",
                lineHeight: 1.7,
                fontSize: { xs: 14, sm: 16 },
              }}
            >
              {product.description || "No full description provided."}
            </Typography>

            <Divider sx={{ my: 3 }} />

            {/* Specifications */}
            {product.specifications && (
              <>
                <Typography
                  fontSize={{ xs: 20, sm: 22 }}
                  fontWeight={700}
                  sx={{ mb: 1 }}
                >
                  Specifications
                </Typography>

                <Typography
                  sx={{
                    color: "#374151",
                    lineHeight: 1.8,
                    fontSize: { xs: 14, sm: 16 },
                  }}
                >
                  {(() => {
                    let specs = product.specifications;
                    if (Array.isArray(specs)) {
                      return specs.map((s, i) => <div key={i}>• {s}</div>);
                    }
                    if (typeof specs === "object") {
                      return Object.entries(specs).map(([key, val]) => (
                        <div key={key}>
                          • <strong>{key}:</strong> {val}
                        </div>
                      ));
                    }
                    return specs;
                  })()}
                </Typography>

                <Divider sx={{ my: 3 }} />
              </>
            )}

            {/* Seller Details */}
            {product.user && (
              <>
                <Typography
                  fontSize={{ xs: 20, sm: 22 }}
                  fontWeight={700}
                  sx={{ mb: 2 }}
                >
                  Seller Details
                </Typography>

                <Box
                  sx={{
                    p: 2,
                    borderRadius: 2,
                    border: "1px solid #e5e7eb",
                    mb: 4,
                  }}
                >
                  <Typography><strong>Name:</strong> {product.user.name}</Typography>
                  <Typography><strong>Email:</strong> {product.user.email}</Typography>
                  <Typography><strong>Phone:</strong> {product.user.phone || "N/A"}</Typography>
                  <Typography><strong>Business:</strong> {product.user.businessName || "N/A"}</Typography>
                  <Typography><strong>Address:</strong> {product.user.businessAddress || "N/A"}</Typography>
                </Box>

                <Divider sx={{ my: 2 }} />
              </>
            )}
          </Box>
        </Box>
      </Box>
    </Box>
  );
}
