import { useDispatch, useSelector } from "react-redux";
import {
  getAllBuyerCategories,
  createBuyerCategory,
} from "../redux/slices/buyerCategoriesSlice";
import {
  getAllSellerCategories,
  createSellerCategory,
} from "../redux/slices/sellerCategoriesSlice";
