export default function Catalog() {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("sm"));
  const dispatch = useDispatch();
  const user = useSelector((state) => state.user.user);
  const [productsByBuyerCategory, setProductsByBuyerCategory] = useState([]);
  const [selectedBuyerCategoryId, setSelectedBuyerCategoryId] = useState(null);
  // Selected buyer category tab
  const [selectedBuyerCategory, setSelectedBuyerCategory] =
    useState("MRP Catalog"); // useState("MRP Catalog");

  // Redux state for buyer categories
  const {
    categories: buyerCategories,
    loading,
    error,
  } = useSelector((state) => state.buyerCategories);

  useEffect(() => {
    dispatch(getAllBuyerCategories());
  }, [dispatch]);

  useEffect(() => {
    const category = buyerCategories.find(
      (b) => b.name === selectedBuyerCategory
    );
    if (category) {
      // fetchProductsByBuyerCategory(category._id);
    } else {
      setProductsByBuyerCategory([]);
    }
  }, [selectedBuyerCategory, buyerCategories]);

  const {
    categories: sellerCategories,
    loading: sellerLoading,
    error: sellerError,
  } = useSelector((state) => state.sellerCategory);

  useEffect(() => {
    dispatch(getAllSellerCategories());
  }, [dispatch]);

  const { userProducts, loading: productLoading } = useSelector(
    (state) => state.products
  );

  useEffect(() => {
    dispatch(getUserProducts()); // Fetch all products or implement pagination
  }, [dispatch]);

  // Current buyer category object
  const currentBuyer = buyerCategories.find(
    (b) => b.name === selectedBuyerCategory
  );

  const categories =
    selectedBuyerCategory === "MRP Catalog"
      ? Array.from(new Set(sellerCategories.map((c) => c.name))) // <- okay, strings here
      : currentBuyer
      ? sellerCategories
          .filter((c) => c.buyerCategory === selectedBuyerCategory)
          .map((c) => c.name)
      : [];

  // Add Product form dynamic categories based on selected buyerCategory
  const [addProductCategories, setAddProductCategories] = useState([]);

  // State for selected category in filter
  const [selectedCategory, setSelectedCategory] = useState("All");

  // States for dialogs
  const [openAddProduct, setOpenAddProduct] = useState(false);
  const [openAddBuyerCategory, setOpenAddBuyerCategory] = useState(false);
  const [openAddProductCategory, setOpenAddProductCategory] = useState(false);

  // Add Product form state (includes buyerCategory)
  const [newProduct, setNewProduct] = useState({
    name: "",
    category: "",
    mrp: "",
    description: "",
    specifications: "",
    image: "",
    imageFile: null,
    unit: "",
    customUnit: "",
  });

  // CSV Upload state
  const [csvFile, setCsvFile] = useState(null);
  const [csvData, setCsvData] = useState([]);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [isUploading, setIsUploading] = useState(false);
  const [openUploadCSV, setOpenUploadCSV] = useState(false);

  // Add these state variables
  const [openUploadXLSX, setOpenUploadXLSX] = useState(false);
  const [xlsxFile, setXlsxFile] = useState(null);
  const [xlsxData, setXlsxData] = useState([]);

  // Add Buyer Category form state (discount instead of gst)
  const [newBuyerCategory, setNewBuyerCategory] = useState({
    name: "",
    discount: "",
  });
  // Limit buyer categories (excluding MRP Catalog which is always shown separately)
  const visibleCategories = buyerCategories.slice(0, 4); // first 4 categories
  const extraCategories = buyerCategories.slice(4); // rest go into "More"
  const [anchorMore, setAnchorMore] = useState(null);
  const handleMoreOpen = (e) => setAnchorMore(e.currentTarget);
  const handleMoreClose = () => setAnchorMore(null);

  // Add Product Category form state (includes gst)
  const [newProductCategory, setNewProductCategory] = useState({
    name: "",
    gst: "",
  });
  const [anchorMoreSeller, setAnchorMoreSeller] = useState(null);
  const handleMoreSellerOpen = (e) => setAnchorMoreSeller(e.currentTarget);
  const handleMoreSellerClose = () => setAnchorMoreSeller(null);

  const visibleSellerCategories = sellerCategories.slice(0, 4);
  const extraSellerCategories = sellerCategories.slice(4);

  // Edit Product form states (unchanged)
  const [editProductId, setEditProductId] = useState(null);
  const [editProduct, setEditProduct] = useState({
    name: "",
    unit: "",
    customUnit: "",
    category: null,
    mrp: "",
    price: "",
    description: "",
    specifications: "",
    image: "",
    imageFile: null,
  });

  const [openEditProduct, setOpenEditProduct] = useState(false);

  // Actions menu state
  const [anchorEl, setAnchorEl] = useState(null);
  const [actionProductId, setActionProductId] = useState(null);

  // Add this state for confirm dialog
  const [confirmDialog, setConfirmDialog] = useState({
    open: false,
    title: "",
    content: "",
    onConfirm: null,
  });

  // Update addProductCategories whenever buyer category changes
  useEffect(() => {
    if (!newProduct.buyerCategory === "MRP Catalog") return;

    const buyerId = newProduct.buyerCategory;
    const filteredCategories = sellerCategories.filter(
      (c) => c.buyerCategory === buyerId
    );

    setAddProductCategories(filteredCategories);
    setNewProduct((prev) => ({ ...prev, category: "" }));
  }, [newProduct.buyerCategory, sellerCategories]);

  let filteredProducts = [];

  if (selectedBuyerCategory === "MRP Catalog") {
    // MRP → Use master product list
    filteredProducts =
      selectedCategory === "All"
        ? userProducts
        : userProducts.filter(
            (p) => p.category?.name === selectedCategory?.name
          );
  } else {
    // Buyer category → use API returned mapped products
    const buyerProducts = productsByBuyerCategory?.products || [];

    filteredProducts =
      selectedCategory === "All"
        ? buyerProducts
        : buyerProducts.filter(
            (p) => p.category?.name === selectedCategory?.name
          );
  }

  // XLSX Upload Handlers
  const handleUploadXLSXOpen = () => {
    setOpenUploadXLSX(true);
    setXlsxFile(null);
    setXlsxData([]);
    setUploadProgress(0);
  };

  const handleUploadXLSXClose = () => {
    setOpenUploadXLSX(false);
    setXlsxFile(null);
    setXlsxData([]);
    setUploadProgress(0);
  };

  const handleXLSXFileSelect = async (event) => {
    const file = event.target.files[0];
    if (
      file &&
      (file.type ===
        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" ||
        file.type === "application/vnd.ms-excel" ||
        file.name.endsWith(".xlsx") ||
        file.name.endsWith(".xls"))
    ) {
      setXlsxFile(file);
      await parseXLSXFile(file);
    } else {
      toast.info("Please select a valid Excel file (.xlsx or .xls)");
    }
  };

  const parseXLSXFile = async (file) => {
    try {
      // Import xlsx library dynamically
      const XLSX = await import("xlsx");

      const reader = new FileReader();
      reader.onload = (e) => {
        const data = new Uint8Array(e.target.result);
        const workbook = XLSX.read(data, { type: "array" });

        // Get first worksheet
        const worksheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[worksheetName];

        // Convert to JSON
        const jsonData = XLSX.utils.sheet_to_json(worksheet);

        // Expected headers from your DownloadXLSX format
        const expectedHeaders = [
          "name",
          "category",
          "mrp",
          // "stock",
          "description",
          "specifications",
          "image",
        ];

        // Validate headers if data exists
        if (jsonData.length > 0) {
          const firstRow = jsonData[0];
          const actualHeaders = Object.keys(firstRow);
          const isValidXLSX = expectedHeaders.every((header) =>
            actualHeaders.includes(header)
          );

          if (!isValidXLSX) {
            toast.info(
              "Invalid Excel format. Please use the template from Download XLSX."
            );
            return;
          }
        }

        const parsedData = [];
        jsonData.forEach((row) => {
          // Validate required fields
          if (
            row.name &&
            row.category &&
            row.mrp !== undefined
            // &&
            // row.stock !== undefined
          ) {
            parsedData.push({
              name: row.name || "",
              category: row.category || "",
              mrp: row.mrp.toString() || "",
              // stock: row.stock.toString() || "",
              description: row.description || "",
              specifications: row.specifications || "",
              image: row.image || "",
            });
          }
        });

        setXlsxData(parsedData);
      };
      reader.readAsArrayBuffer(file);
    } catch (error) {
      toast.error(
        "Error reading Excel file. Please make sure it is a valid Excel file."
      );
    }
  };

  const handleBulkUpload = async () => {
    if (!xlsxData.length) {
      toast.warning("No valid data to upload");
      return;
    }

    setIsUploading(true);
    setUploadProgress(0);

    try {
      const totalProducts = xlsxData.length;
      let successCount = 0;
      let errorCount = 0;

      for (let i = 0; i < xlsxData.length; i++) {
        const product = xlsxData[i];

        try {
          // Find category ID by name
          const category = sellerCategories.find(
            (cat) => cat.name.toLowerCase() === product.category.toLowerCase()
          );

          if (!category) {
            toast.warning(`Category not found: ${product.category}`);
            errorCount++;
            continue;
          }

          const formData = new FormData();
          formData.append("name", product.name);
          formData.append("category", category._id);
          formData.append("mrp", product.mrp);
          // formData.append("stock", product.stock);
          formData.append("description", product.description || "");
          formData.append("specifications", product.specifications || "");
          // formData.append("user", user?._id);
          formData.append("image", product.image || "");

          await dispatch(addProduct(formData)).unwrap();
          successCount++;

          // Update progress
          setUploadProgress(Math.round(((i + 1) / totalProducts) * 100));
        } catch (error) {
          errorCount++;
        }
      }

      setIsUploading(false);

      if (successCount > 0) {
        toast.success(
          `Successfully uploaded ${successCount} products. ${errorCount} failed.`
        );
        handleUploadXLSXClose();
        dispatch(getUserProducts()); // Refresh products
      } else {
        toast.error(
          "Failed to upload any products. Please check your Excel data."
        );
      }
    } catch (error) {
      setIsUploading(false);
      toast.error("Bulk upload failed: " + (error.message || "Unknown error"));
    }
  };

  // Handlers for Add Product Dialog
  const handleAddProductOpen = () => {
    setNewProduct({
      name: "",
      category: "",
      mrp: "",
      unit: "",
      customUnit: "",
      description: "",
      specifications: "",
      image: "",
      imageFile: null,
    });
    setOpenAddProduct(true);
  };

  const handleAddProductClose = () => {
    setOpenAddProduct(false);
    setNewProduct({
      name: "",
      category: "",
      mrp: "",
      unit: "",
      customUnit: "",
      // stock: "",
      description: "",
      specifications: "",
      image: "",
      imageFile: null,
    });
  };

  const handleAddProductChange = (e) => {
    const { name, value, type, checked } = e.target;
    setNewProduct((prev) => ({
      ...prev,
      [name]: type === "checkbox" ? checked : value,
    }));
  };

  // Add Product submit handler with image upload
  const handleAddProductSubmit = async (e) => {
    e.preventDefault();
    if (
      !newProduct.name ||
      !newProduct.category ||
      !newProduct.mrp
      // ||
      // !newProduct.stock
    ) {
      toast.warning("Please fill all fields");
      return;
    }

    const formData = new FormData();
    formData.append("name", newProduct.name);
    formData.append("category", newProduct.category);
    formData.append("mrp", newProduct.mrp);
    const finalUnit =
      newProduct.unit === "other" ? newProduct.customUnit : newProduct.unit;

    formData.append("unit", finalUnit);
    // formData.append("stock", newProduct.stock);
    formData.append("description", newProduct.description || "");
    formData.append("specifications", newProduct.specifications || "");
    // formData.append("buyerCategory", newProduct.buyerCategory);
    formData.append("user", user?._id);
    formData.append("image", newProduct.image); // If you handle image upload
    try {
      await dispatch(addProduct(formData)).unwrap();
      await dispatch(getUserProducts({ page: 1, limit: 100 }));
      toast.success("Product added successfully");
      handleAddProductClose();
    } catch (err) {
      toast.error(err?.message || "Failed to add product");
    }
  };

  // Edit product handlers
  const handleEditProductOpen = (product) => {
    // Find the buyer category price
    const buyerProduct = productsByBuyerCategory?.products?.find(
      (p) => p._id === product._id
    );

    const priceToShow = buyerProduct?.buyerCategory?.price ?? product.price;

    // Check if unit is a custom unit
    const isCustomUnit = !["kgs", "meters", "pieces"].includes(
      product.unit?.toLowerCase()
    );
    const displayUnit = isCustomUnit ? "other" : product.unit || "";

    // Set editProduct with proper unit handling
    setEditProduct({
      ...product,
      price: priceToShow,
      unit: displayUnit,
      customUnit: isCustomUnit ? product.unit : "",
    });

    setEditProductId(product?._id);
    setOpenEditProduct(true);
    setAnchorEl(null);
    setActionProductId(null);
  };

  const handleEditProductClose = async () => {
    setOpenEditProduct(false);
    setEditProductId(null);
    setEditProduct({
      name: "",
      category: "",
      price: "",
      unit: "",
      customUnit: "",
      mrp: "",
      // stock: "",
    });
    await dispatch(getUserProducts({ page: 1, limit: 100 }));
  };

  const handleEditProductChange = (e) => {
    const { name, value, type, checked } = e.target;

    // Special handling for unit changes
    if (name === "unit") {
      setEditProduct((prev) => ({
        ...prev,
        unit: value,
        // Reset customUnit when switching away from "other"
        customUnit: value === "other" ? prev.customUnit : "",
      }));
    } else {
      setEditProduct((prev) => ({
        ...prev,
        [name]: type === "checkbox" ? checked : value,
      }));
    }
  };

  // Edit product submit handler with image upload
  const handleEditProductSubmit = async (e) => {
    e.preventDefault();

    try {
      if (
        !editProduct.name ||
        !editProduct.category ||
        !editProduct.price
        // ||
        // !editProduct.stock
      ) {
        toast.warning("Please fill all required fields");
        return;
      }

      const categoryId = editProduct.category?._id || editProduct.category;

      if (!categoryId) {
        toast.warning("Please select valid categories");
        return;
      }

      // Buyer Category validation
      if (!selectedBuyerCategoryId) {
        toast.warning("Please select a valid buyer category");
        return;
      }

      // Calculate final unit
      const finalUnit =
        editProduct.unit === "other"
          ? editProduct.customUnit
          : editProduct.unit;

      const formData = new FormData();
      formData.append("name", editProduct.name || "");
      formData.append("unit", finalUnit);
      formData.append("category", categoryId);
      formData.append("mrp", editProduct.mrp?.toString() || "0");
      formData.append("price", editProduct.price?.toString() || "0");
      // formData.append("stock", editProduct.stock?.toString() || "0");
      formData.append("user", user?._id || "");
      formData.append("description", editProduct.description || "");
      formData.append("specifications", editProduct.specifications || "");
      formData.append("buyerCategory", selectedBuyerCategoryId || "");

      if (editProduct.imageFile) {
        const reader = new FileReader();
        reader.onloadend = async () => {
          formData.append("image", reader.result); // Base64 string
          try {
            await dispatch(
              updateProduct({ id: editProductId, formData })
            ).unwrap();
            await dispatch(getUserProducts({ page: 1, limit: 100 }));
            handleEditProductClose();

            if (editProduct.image && editProduct.image.startsWith("blob:")) {
              URL.revokeObjectURL(editProduct.image);
            }
          } catch (err) {
            toast.error(err?.message || "Failed to update product");
          }
        };
        reader.readAsDataURL(editProduct.imageFile);
        return;
      }

      if (editProduct.image) {
        formData.append("image", editProduct.image);
      }
      await dispatch(updateProduct({ id: editProductId, formData })).unwrap();
      await dispatch(getUserProducts({ page: 1, limit: 100 }));
      handleEditProductClose();
    } catch (err) {
      toast.error(err?.message || "Failed to update product");
    }
  };

  // Actions menu handlers
  const handleActionsMenuOpen = (event, id) => {
    setAnchorEl(event.currentTarget);
    setActionProductId(id);
  };

  const handleActionsMenuClose = () => {
    setAnchorEl(null);
    setActionProductId(null);
  };

  // Toggle product visibility handler
  const handleToggleProductVisible = async (productId) => {
    try {
      // Find current product data from productsByBuyerCategory
      const productInBuyerCategory = productsByBuyerCategory?.products?.find(
        (p) => p._id === productId
      );

      if (!productInBuyerCategory) {
        toast.info("Product not found in buyer category");
        return;
      }

      // Get current visibility - directly from buyerCategory.visible
      const currentVisibility =
        productInBuyerCategory.buyerCategory?.visible ?? false;
      const newVisibility = !currentVisibility;

      // API call to update visibility
      await dispatch(
        updateProductBuyerCategoryVisibility({
          productId,
          buyerCategory: selectedBuyerCategoryId,
          visible: newVisibility,
        })
      ).unwrap();

      await dispatch(getUserProducts({ page: 1, limit: 100 }));

      // Manually update the local state for immediate UI update
      setProductsByBuyerCategory((prev) => ({
        ...prev,
        products: prev.products.map((p) =>
          p._id === productId
            ? {
                ...p,
                buyerCategory: {
                  ...p.buyerCategory,
                  visible: newVisibility,
                },
              }
            : p
        ),
      }));
    } catch (error) {
      toast.error("Failed to update visibility");
    }
  };

  // Buyer category selection handler
  const handleBuyerCategorySelect = async (category) => {
    setSelectedBuyerCategory(category.name || category); // update name for UI
    setSelectedBuyerCategoryId(category._id); // store ID for API calls
    setSelectedCategory("All");
    if (category._id) {
      // call API only for actual buyer categories
      dispatch(getProductsByBuyerCategoryId(category._id));
    }
  };

  useEffect(() => {
    if (selectedBuyerCategoryId) {
      const fetchProducts = async () => {
        try {
          const resultAction = await dispatch(
            getProductsByBuyerCategoryId(selectedBuyerCategoryId)
          ).unwrap();
          setProductsByBuyerCategory(resultAction || []);
        } catch (err) {
          toast.error("Failed to fetch products by buyer category:", err);
        }
      };
      fetchProducts();
    } else {
      setProductsByBuyerCategory([]);
    }
  }, [selectedBuyerCategoryId, dispatch]);

  // Add Buyer Category handlers with Discount instead of GST
  // const handleAddBuyerCategoryOpen = () => setOpenAddBuyerCategory(true);
  const handleAddBuyerCategoryClose = () => {
    setOpenAddBuyerCategory(false);
    setNewBuyerCategory({ name: "", discount: "" });
  };

  const handleAddBuyerCategoryChange = (e) => {
    const { name, value } = e.target;
    setNewBuyerCategory((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleAddBuyerCategorySubmit = async (e) => {
    e.preventDefault();
    if (!newBuyerCategory.name || newBuyerCategory.discount === "") {
      toast.warning("Please fill all fields");
      return;
    }
    // dispatch API call
    dispatch(createBuyerCategory(newBuyerCategory));
    handleAddBuyerCategoryClose();
  };

  // Add Product Category handlers with GST field
  // const handleAddProductCategoryOpen = () => setOpenAddProductCategory(true);
  const handleAddProductCategoryClose = () => {
    setOpenAddProductCategory(false);
    setNewProductCategory({ name: "", gst: "" });
  };

  const handleAddProductCategoryChange = (e) => {
    const { name, value } = e.target;
    setNewProductCategory((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleAddProductCategorySubmit = (e) => {
    e.preventDefault();
    if (!newProductCategory.name || newProductCategory.gst === "") {
      toast.info("Please fill all fields");
      return;
    }
    if (categories?.includes(newProductCategory?.name)) {
      toast.warning("This category already exists in current buyer category");
      return;
    }

    // Dispatch Redux update
    dispatch(createSellerCategory(newProductCategory));
    dispatch(getAllSellerCategories());

    handleAddProductCategoryClose();
  };

  // Delete product handler
  const handleDeleteProduct = (id, productName) => {
    setConfirmDialog({
      open: true,
      title: "Delete Product",
      content: `Are you sure you want to delete "${productName}"?`,
      onConfirm: () => performDeleteProduct(id),
      severity: "error",
      confirmText: "Delete",
    });
    handleActionsMenuClose();
  };

  // Actual delete function
  const performDeleteProduct = async (id) => {
    try {
      await dispatch(deleteProduct(id)).unwrap();
      dispatch(getUserProducts({ page: 1, limit: 100 }));
      setConfirmDialog((prev) => ({ ...prev, open: false }));

      // Simple success message
      toast.success("Product deleted successfully!");
    } catch (err) {
      toast.error(err?.message || "Failed to delete product");
      setConfirmDialog((prev) => ({ ...prev, open: false }));
    }
  };

  // Confirm dialog close handler
  const handleConfirmDialogClose = () => {
    setConfirmDialog((prev) => ({ ...prev, open: false }));
  };

  return (
    <Box
      sx={{
        width: "100%",
        minHeight: "100vh",
        background: "#f8fafc",
        px: { xs: 2, sm: 4, md: 7, lg: 12 },
        py: { xs: 2, sm: 4, md: 5 },
        boxSizing: "border-box",
        display: "flex",
        justifyContent: "center",
      }}
    >
      <Box
        sx={{
          maxWidth: 1400,
          width: "100%",
          mx: "auto",
          paddingRight: "10px",
          boxSizing: "border-box",
        }}
      >
        {/* Header */}
        <Box
          sx={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            flexWrap: "wrap",
            mb: 3,
          }}
        >
          <Typography
            variant={isMobile ? "h5" : "h4"}
            fontWeight={700}
            color="text.primary"
            sx={{ mb: isMobile ? 2 : 0 }}
          >
            Catalog Management
          </Typography>
          <Box sx={{ display: "flex", gap: 1 }}>
            <Box mb={-2}>
              <DownloadCSV />
            </Box>
            <Button
              variant="outlined"
              startIcon={<CloudUploadOutlinedIcon />}
              sx={{
                bgcolor: "white",
                px: 1.5,
                minWidth: 36,
                fontWeight: 600,
                fontSize: 14,
                borderColor: "#95a4d7",
                "&:hover": {
                  bgcolor: "rgba(30, 94, 255, 0.1)",
                },
              }}
              onClick={handleUploadXLSXOpen}
            >
              Upload XLSX
            </Button>
            <Button
              variant="contained"
              startIcon={<AddCircleOutlineIcon />}
              sx={{
                bgcolor: "#1344a4",
                px: 2,
                minWidth: 110,
                fontWeight: 700,
                fontSize: 16,
                "&:hover": {
                  bgcolor: "#0e3877",
                },
              }}
              onClick={handleAddProductOpen}
            >
              Add Product
            </Button>
          </Box>
        </Box>
        <Box
          sx={{
            display: "flex",
            flexWrap: isMobile ? "wrap" : "nowrap",
            gap: 1,
            mb: 3,
            overflowX: isMobile ? "visible" : "auto",
          }}
        >
          {/* MRP Catalog - always visible */}
          <Button
            variant={
              selectedBuyerCategory === "MRP Catalog" ? "contained" : "outlined"
            }
            onClick={() => handleBuyerCategorySelect("MRP Catalog")}
            sx={{
              borderRadius: "40px",
              minWidth: 100,
              fontWeight: 700,
              px: 2,
              bgcolor:
                selectedBuyerCategory === "MRP Catalog" ? "#1344a4" : "white",
              color:
                selectedBuyerCategory === "MRP Catalog" ? "white" : "#1344a4",
            }}
          >
            MRP Catalog
          </Button>
          {/* First 4 buyer categories */}
          {visibleCategories.map((cat) => (
            <Button
              key={cat._id}
              variant={
                selectedBuyerCategory === cat.name ? "contained" : "outlined"
              }
              onClick={() => handleBuyerCategorySelect(cat)}
              sx={{
                borderRadius: "40px",
                minWidth: 100,
                fontWeight: 700,
                px: 2,
                bgcolor:
                  selectedBuyerCategory === cat.name ? "#1344a4" : "white",
                color: selectedBuyerCategory === cat.name ? "white" : "#1344a4",
              }}
            >
              {cat.name}
              {/* {cat.discount && `| Discount: ${cat.discount}%`} */}
            </Button>
          ))}

          {/* More dropdown if extra exist */}
          {extraCategories.length > 0 && (
            <>
              <Button
                variant="outlined"
                onClick={handleMoreOpen}
                sx={{
                  borderRadius: "40px",
                  minWidth: 100,
                  fontWeight: 700,
                  px: 2,
                  color: "#1344a4",
                }}
              >
                More
              </Button>
              <Menu
                anchorEl={anchorMore}
                open={Boolean(anchorMore)}
                onClose={handleMoreClose}
              >
                {extraCategories.map(({ name, discount }) => (
                  <MenuItem
                    key={name}
                    onClick={() => {
                      handleBuyerCategorySelect(name);
                      handleMoreClose();
                    }}
                  >
                    {name}
                    {/* {discount && `| Discount: ${discount}%`} */}
                  </MenuItem>
                ))}
              </Menu>
            </>
          )}
        </Box>

        {/* Product (Seller) Categories */}
        <Box
          sx={{
            display: "flex",
            flexWrap: isMobile ? "wrap" : "nowrap",
            gap: 1,
            mb: 3,
            overflowX: isMobile ? "visible" : "auto",
          }}
        >
          {/* First 4 seller categories */}
          {/* {visibleSellerCategories.map((cat) => (
            <>
            <Button
              key={cat._id}
              variant={
                selectedCategory?.name === cat.name ? "contained" : "outlined"
              }
              onClick={() => setSelectedCategory(cat)}
              sx={{
                borderRadius: "40px",
                minWidth: 120,
                fontWeight: 700,
                px: 2,
              }}
            >
              {cat.name}
               <Avatar
              src={cat?.image}
              sx={{ width: 30, height: 30, mt: 2, borderRadius: 1 }}
            />
            </Button>

            
            </>
          ))} */}
          {visibleSellerCategories.map((cat) => (
            <Button
              key={cat._id}
              variant={
                selectedCategory?.name === cat.name ? "contained" : "outlined"
              }
              onClick={() => setSelectedCategory(cat)}
              sx={{
                borderRadius: "40px",
                minWidth: 140,
                fontWeight: 700,
                px: 2,
                display: "flex",
                alignItems: "center",
                gap: 1, // space between text and avatar
                textTransform: "none",
                mb: 1, // optional spacing between buttons
              }}
            >
              {cat.image && (
                <Avatar
                  src={cat.image}
                  sx={{ width: 30, height: 30, borderRadius: 50 }}
                />
              )}
              {cat.name}
            </Button>
          ))}

          {/* More dropdown */}
          {extraSellerCategories.length > 0 && (
            <>
              <Button
                variant="outlined"
                onClick={handleMoreSellerOpen}
                sx={{
                  borderRadius: "40px",
                  minWidth: 100,
                  fontWeight: 700,
                  px: 2,
                }}
              >
                More
              </Button>
              <Menu
                anchorEl={anchorMoreSeller}
                open={Boolean(anchorMoreSeller)}
                onClose={handleMoreSellerClose}
              >
                {extraSellerCategories.map((cat) => (
                  <MenuItem
                    key={cat._id}
                    onClick={() => {
                      setSelectedCategory(cat);
                      handleMoreSellerClose();
                    }}
                  >
                    {cat.name}
                  </MenuItem>
                ))}
              </Menu>
            </>
          )}
        </Box>

        {/* Product Table */}
        <Box sx={{ overflowX: "auto" }}>
          <TableContainer>
            <Box sx={{ overflowX: "auto" }}>
              <TableContainer>
                <Table stickyHeader sx={{ minWidth: 650 }}>
                  <TableHead>
                    <TableRow>
                      <TableCell>#</TableCell>
                      <TableCell>Image</TableCell>
                      <TableCell>Name</TableCell>
                      <TableCell>Category</TableCell>

                      {selectedBuyerCategory === "MRP Catalog" ? (
                        //  MRP Catalog headers
                        <>
                          <TableCell>MRP</TableCell>
                          <TableCell>Actions</TableCell>
                        </>
                      ) : (
                        //  Other buyer categories headers
                        <>
                          <TableCell>Unit</TableCell>
                          <TableCell>MRP</TableCell>
                          <TableCell>Price</TableCell>
                          <TableCell>Visible</TableCell>
                          <TableCell>Actions</TableCell>
                        </>
                      )}
                    </TableRow>
                  </TableHead>

                  <TableBody>
                    {filteredProducts?.map((product, index) => {
                      const buyerProduct =
                        productsByBuyerCategory?.products?.find(
                          (p) => p._id === product._id
                        );

                      const priceToShow =
                        buyerProduct?.buyerCategory?.price ?? product.price;

                      return (
                        <TableRow key={product._id}>
                          <TableCell>{index + 1}</TableCell>
                          {/* Image */}
                          <TableCell>
                            <Box
                              sx={{
                                width: 40,
                                height: 40,
                                bgcolor: "#e7fafc",
                                color: "#a0b7a8",
                                fontWeight: 700,
                                fontSize: 15,
                                borderRadius: 2,
                                display: "flex",
                                justifyContent: "center",
                                alignItems: "center",
                              }}
                            >
                              {product.image ? (
                                <img
                                  src={product.image}
                                  alt={product.name}
                                  style={{
                                    width: "100%",
                                    height: "100%",
                                    objectFit: "cover",
                                    borderRadius: 8,
                                  }}
                                />
                              ) : (
                                "IMG"
                              )}
                            </Box>
                          </TableCell>

                          {/* Name */}
                          <TableCell
                            sx={{
                              whiteSpace: "nowrap",
                              overflow: "hidden",
                              textOverflow: "ellipsis",
                            }}
                          >
                            {product.name}
                          </TableCell>

                          {/* Category */}
                          <TableCell>{product.category?.name}</TableCell>

                          {selectedBuyerCategory === "MRP Catalog" ? (
                            <>
                              <TableCell>{product.mrp?.toFixed(2)}</TableCell>
                              <TableCell>
                                <IconButton
                                  onClick={(e) =>
                                    handleActionsMenuOpen(e, product._id)
                                  }
                                  size="small"
                                  sx={{ p: 0.5 }}
                                >
                                  <MoreHorizIcon />
                                </IconButton>
                                <Menu
                                  anchorEl={anchorEl}
                                  open={
                                    actionProductId === product._id &&
                                    Boolean(anchorEl)
                                  }
                                  onClose={handleActionsMenuClose}
                                  anchorOrigin={{
                                    vertical: "bottom",
                                    horizontal: "right",
                                  }}
                                  transformOrigin={{
                                    vertical: "top",
                                    horizontal: "right",
                                  }}
                                >
                                  <MenuItem
                                    onClick={() =>
                                      handleEditProductOpen(product)
                                    }
                                  >
                                    <ListItemIcon>
                                      <EditIcon fontSize="small" />
                                    </ListItemIcon>
                                    <ListItemText>Edit</ListItemText>
                                  </MenuItem>
                                  <MenuItem
                                    onClick={() =>
                                      handleDeleteProduct(
                                        product._id,
                                        product.name
                                      )
                                    }
                                  >
                                    <ListItemIcon>
                                      <DeleteIcon
                                        fontSize="small"
                                        color="error"
                                      />
                                    </ListItemIcon>
                                    <ListItemText>Delete</ListItemText>
                                  </MenuItem>
                                </Menu>
                              </TableCell>
                            </>
                          ) : (
                            <>
                              <TableCell>{product.unit}</TableCell>
                              <TableCell>{product.mrp?.toFixed(2)}</TableCell>
                              <TableCell>{priceToShow?.toFixed(2)}</TableCell>
                              <TableCell>
                                <Switch
                                  checked={
                                    buyerProduct?.buyerCategory?.visible ??
                                    false
                                  }
                                  onChange={() =>
                                    handleToggleProductVisible(product._id)
                                  }
                                  color="primary"
                                  size="small"
                                />
                              </TableCell>

                              <TableCell>
                                <IconButton
                                  onClick={(e) =>
                                    handleActionsMenuOpen(e, product._id)
                                  }
                                  size="small"
                                  sx={{ p: 0.5 }}
                                >
                                  <MoreHorizIcon />
                                </IconButton>
                                <Menu
                                  anchorEl={anchorEl}
                                  open={
                                    actionProductId === product._id &&
                                    Boolean(anchorEl)
                                  }
                                  onClose={handleActionsMenuClose}
                                  anchorOrigin={{
                                    vertical: "bottom",
                                    horizontal: "right",
                                  }}
                                  transformOrigin={{
                                    vertical: "top",
                                    horizontal: "right",
                                  }}
                                >
                                  <MenuItem
                                    onClick={() =>
                                      handleEditProductOpen(product)
                                    }
                                  >
                                    <ListItemIcon>
                                      <EditIcon fontSize="small" />
                                    </ListItemIcon>
                                    <ListItemText>Edit</ListItemText>
                                  </MenuItem>
                                  <MenuItem
                                    onClick={() =>
                                      handleDeleteProduct(
                                        product._id,
                                        product.name
                                      )
                                    }
                                  >
                                    <ListItemIcon>
                                      <DeleteIcon
                                        fontSize="small"
                                        color="error"
                                      />
                                    </ListItemIcon>
                                    <ListItemText>Delete</ListItemText>
                                  </MenuItem>
                                </Menu>
                              </TableCell>
                            </>
                          )}
                        </TableRow>
                      );
                    })}
                  </TableBody>
                </Table>
              </TableContainer>
            </Box>
          </TableContainer>
        </Box>
      </Box>
      {/* Add the XLSX Upload Dialog component: */}
      <Dialog
        open={openUploadXLSX}
        onClose={handleUploadXLSXClose}
        fullWidth
        maxWidth="sm"
      >
        <DialogTitle>
          Upload Excel File
          <IconButton
            onClick={handleUploadXLSXClose}
            sx={{ position: "absolute", right: 12, top: 12 }}
            size="small"
          >
            <CloseIcon />
          </IconButton>
        </DialogTitle>
        <DialogContent sx={{ px: { xs: 1, sm: 3 }, py: 2 }} dividers>
          <Box sx={{ display: "flex", flexDirection: "column", gap: 3 }}>
            <Typography variant="body2" color="text.secondary">
              Upload an Excel file (.xlsx) with the following columns: name,
              category, mrp, description, specifications, image
            </Typography>

            <Button
              variant="outlined"
              component="label"
              startIcon={<CloudUploadOutlinedIcon />}
              sx={{ py: 1.5 }}
            >
              Select Excel File
              <input
                type="file"
                accept=".xlsx,.xls"
                hidden
                onChange={handleXLSXFileSelect}
              />
            </Button>

            {xlsxFile && (
              <Typography variant="body2">
                Selected file: {xlsxFile.name}
              </Typography>
            )}

            {xlsxData.length > 0 && (
              <Box>
                <Typography variant="body2" sx={{ mb: 1 }}>
                  Found {xlsxData.length} products to upload:
                </Typography>
                <Box
                  sx={{
                    maxHeight: 200,
                    overflow: "auto",
                    border: "1px solid #ddd",
                    borderRadius: 1,
                    p: 1,
                  }}
                >
                  {xlsxData.map((product, index) => (
                    <Typography
                      key={index}
                      variant="body2"
                      sx={{ fontSize: "0.8rem", py: 0.5 }}
                    >
                      • {product.name} - {product.category} - ₹{product.mrp}
                    </Typography>
                  ))}
                </Box>
              </Box>
            )}

            {isUploading && (
              <Box sx={{ width: "100%" }}>
                <Typography variant="body2" sx={{ mb: 1 }}>
                  Uploading... {uploadProgress}%
                </Typography>
                <Box
                  sx={{
                    width: "100%",
                    height: 8,
                    bgcolor: "#f0f0f0",
                    borderRadius: 4,
                  }}
                >
                  <Box
                    sx={{
                      width: `${uploadProgress}%`,
                      height: "100%",
                      bgcolor: "#1344a4",
                      borderRadius: 4,
                      transition: "width 0.3s ease",
                    }}
                  />
                </Box>
              </Box>
            )}
          </Box>
        </DialogContent>
        <DialogActions sx={{ px: 3, py: 2 }}>
          <Button onClick={handleUploadXLSXClose} disabled={isUploading}>
            Cancel
          </Button>
          <Button
            onClick={handleBulkUpload}
            variant="contained"
            disabled={!xlsxData.length || isUploading}
          >
            {isUploading ? "Uploading..." : "Upload Products"}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Add Product Dialog */}
      <Dialog
        open={openAddProduct}
        onClose={handleAddProductClose}
        fullWidth
        maxWidth="sm"
        scroll="body"
      >
        <DialogTitle>
          Add Product
          <IconButton
            onClick={handleAddProductClose}
            sx={{ position: "absolute", right: 12, top: 12 }}
            size="small"
          >
            <CloseIcon />
          </IconButton>
        </DialogTitle>
        <DialogContent sx={{ px: { xs: 1, sm: 3 }, py: 2 }} dividers>
          <Box
            component="form"
            onSubmit={handleAddProductSubmit}
            sx={{ display: "flex", flexDirection: "column", gap: 2 }}
          >
            <TextField
              label="Product Category"
              name="category"
              value={newProduct.category}
              onChange={handleAddProductChange}
              select
              required
              fullWidth
              size="small"
            >
              {sellerCategories?.map((cat) => (
                <MenuItem key={cat?._id} value={cat?._id}>
                  {cat.name}
                </MenuItem>
              ))}
            </TextField>

            <TextField
              label="Product Name"
              name="name"
              value={newProduct.name}
              onChange={handleAddProductChange}
              required
              fullWidth
              size="small"
            />
            {/* Unit Selection */}
            <TextField
              label="Unit"
              name="unit"
              value={newProduct.unit}
              onChange={handleAddProductChange}
              select
              fullWidth
              size="small"
            >
              <MenuItem value="kgs">Kgs</MenuItem>
              <MenuItem value="meters">Meters</MenuItem>
              <MenuItem value="pieces">Pieces</MenuItem>
              <MenuItem value="other">Other</MenuItem>
            </TextField>

            {/* Custom unit field appears only when "other" selected */}
            {newProduct.unit === "other" && (
              <TextField
                label="Enter Unit"
                name="customUnit"
                value={newProduct.customUnit}
                onChange={handleAddProductChange}
                fullWidth
                size="small"
                placeholder="Type your custom unit"
              />
            )}

            <TextField
              label="MRP"
              name="mrp"
              value={newProduct.mrp}
              onChange={handleAddProductChange}
              type="number"
              required
              fullWidth
              size="small"
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">₹</InputAdornment>
                ),
              }}
            />
            <TextField
              label="Description"
              name="description"
              value={newProduct.description}
              onChange={handleAddProductChange}
              multiline
              rows={3}
              fullWidth
              size="small"
              placeholder="Optional"
            />
            <TextField
              label="Specifications"
              name="specifications"
              value={newProduct.specifications}
              onChange={handleAddProductChange}
              multiline
              rows={3}
              fullWidth
              size="small"
              placeholder="Optional"
            />
            <TextField
              type="file"
              inputProps={{ accept: "image/*" }}
              onChange={(e) => {
                const file = e.target.files[0];
                if (file) {
                  const reader = new FileReader();
                  reader.onloadend = () => {
                    setNewProduct((prev) => ({
                      ...prev,
                      image: reader.result,
                    })); // Base64 string
                  };
                  reader.readAsDataURL(file);
                }
              }}
              fullWidth
              size="small"
            />
            <DialogActions sx={{ px: 0 }}>
              <Button onClick={handleAddProductClose}>Cancel</Button>
              <Button type="submit" variant="contained">
                Add Product
              </Button>
            </DialogActions>
          </Box>
        </DialogContent>
      </Dialog>

      {/*  Edit Product Dialog */}
      <Dialog
        open={openEditProduct}
        onClose={handleEditProductClose}
        fullWidth
        maxWidth="sm"
        scroll="body"
      >
        <DialogTitle>
          Edit Product
          <IconButton
            onClick={handleEditProductClose}
            sx={{ position: "absolute", right: 12, top: 12 }}
            size="small"
          >
            <CloseIcon />
          </IconButton>
        </DialogTitle>
        <DialogContent sx={{ px: { xs: 1, sm: 3 }, py: 2 }} dividers>
          <Box
            component="form"
            onSubmit={handleEditProductSubmit}
            sx={{ display: "flex", flexDirection: "column", gap: 2 }}
          >
            {/* Seller Categories */}
            <TextField
              label="Category"
              name="category"
              value={editProduct.category?.name || ""}
              onChange={handleEditProductChange}
              select
              required
              fullWidth
              size="small"
            >
              {sellerCategories?.map((cat) => (
                <MenuItem
                  key={cat._id}
                  value={cat.name} // display name
                  onClick={
                    () => setEditProduct((prev) => ({ ...prev, category: cat })) // save full object
                  }
                >
                  {cat.name}
                </MenuItem>
              ))}
            </TextField>

            {/* Product Name */}
            <TextField
              label="Product Name"
              name="name"
              value={editProduct.name}
              onChange={handleEditProductChange}
              required
              fullWidth
              size="small"
            />

            {/* Unit Selection */}
            <TextField
              label="Unit"
              name="unit"
              value={editProduct.unit || ""}
              onChange={handleEditProductChange}
              select
              fullWidth
              size="small"
            >
              <MenuItem value="kgs">Kgs</MenuItem>
              <MenuItem value="meters">Meters</MenuItem>
              <MenuItem value="pieces">Pieces</MenuItem>
              <MenuItem value="other">Other</MenuItem>
            </TextField>
            {/* Custom unit field appears only when "other" selected */}
            {editProduct.unit === "other" && (
              <TextField
                label="Enter Unit"
                name="customUnit"
                value={editProduct.customUnit}
                onChange={handleEditProductChange}
                fullWidth
                size="small"
                placeholder="Type your custom unit"
                required={editProduct.unit === "other"}
              />
            )}

            <TextField
              label="MRP"
              name="mrp"
              value={editProduct.mrp}
              onChange={handleEditProductChange}
              type="number"
              required
              fullWidth
              size="small"
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">₹</InputAdornment>
                ),
              }}
            />

            {/* Price */}
            <TextField
              label="Price"
              name="price"
              value={editProduct.price}
              onChange={handleEditProductChange}
              type="number"
              required
              fullWidth
              size="small"
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">₹</InputAdornment>
                ),
              }}
            />
            <TextField
              label="Description"
              name="description"
              value={editProduct.description}
              onChange={handleEditProductChange}
              multiline
              rows={3}
              fullWidth
              size="small"
              placeholder="Optional"
            />
            <TextField
              label="Specifications"
              name="specifications"
              value={editProduct.specifications}
              onChange={handleEditProductChange}
              multiline
              rows={3}
              fullWidth
              size="small"
              placeholder="Optional"
            />

            <TextField
              type="file"
              inputProps={{ accept: "image/*" }}
              onChange={(e) => {
                const file = e.target.files[0];
                if (file) {
                  const objectUrl = URL.createObjectURL(file);
                  setEditProduct((prev) => ({
                    ...prev,
                    image: objectUrl,
                    imageFile: file,
                  }));
                } else {
                  setEditProduct((prev) => ({
                    ...prev,
                    image: "",
                    imageFile: null,
                  }));
                }
              }}
              fullWidth
              size="small"
            />

            {/* Preview */}
            {editProduct.image && (
              <Box
                sx={{
                  width: 80,
                  height: 80,
                  borderRadius: 2,
                  overflow: "hidden",
                  mt: 1,
                }}
              >
                <img
                  src={editProduct.image}
                  alt="Preview"
                  style={{ width: "100%", height: "100%", objectFit: "cover" }}
                />
              </Box>
            )}
            <DialogActions sx={{ px: 0 }}>
              <Button onClick={handleEditProductClose}>Cancel</Button>
              <Button type="submit" variant="contained">
                Save Changes
              </Button>
            </DialogActions>
          </Box>
        </DialogContent>
      </Dialog>

      {/* Add Buyer Category Dialog */}
      <AddBuyerCategoryDialog
        open={openAddBuyerCategory}
        handleClose={handleAddBuyerCategoryClose}
        newBuyerCategory={newBuyerCategory}
        handleChange={handleAddBuyerCategoryChange}
        handleSubmit={handleAddBuyerCategorySubmit}
      />

      {/* Add Seller Category Dialog */}
      <AddSellerCategoryDialog
        open={openAddProductCategory}
        handleClose={handleAddProductCategoryClose}
        newSellerCategory={newProductCategory}
        handleChange={handleAddProductCategoryChange}
        handleSubmit={handleAddProductCategorySubmit}
      />
      {/* Confirm Dialog for Delete */}
      <ConfirmDialog
        open={confirmDialog.open}
        title={confirmDialog.title}
        content={confirmDialog.content}
        onConfirm={confirmDialog.onConfirm}
        onClose={handleConfirmDialogClose}
      />
    </Box>
  );
}
